<?php
namespace Avanik;
defined('ABSPATH') || exit;
final class NotificationDeliveryLog {
 private static function table(): string { global $wpdb; return $wpdb->prefix.'avanik_notification_delivery_log'; }
 public static function register(): void { add_action('init',[self::class,'install']); add_action('avanik_notification_delivery_attempt',[self::class,'attempt'],10,5); add_action('avanik_notification_delivery_result',[self::class,'result'],10,11); add_action('admin_menu',[self::class,'menu']); }
 public static function install(): void { global $wpdb; require_once ABSPATH.'wp-admin/includes/upgrade.php'; $t=self::table(); $c=$wpdb->get_charset_collate(); dbDelta("CREATE TABLE {$t} (id bigint unsigned NOT NULL AUTO_INCREMENT,queue_id bigint unsigned NOT NULL,event varchar(80) NOT NULL,role varchar(30) NOT NULL,user_id bigint unsigned NOT NULL DEFAULT 0,channel varchar(30) NOT NULL,provider varchar(80) NOT NULL DEFAULT '',attempt int unsigned NOT NULL DEFAULT 1,status varchar(30) NOT NULL DEFAULT 'attempted',provider_message_id varchar(190) NOT NULL DEFAULT '',error_code varchar(80) NOT NULL DEFAULT '',error_message text NULL,metadata longtext NULL,created_at datetime NOT NULL,PRIMARY KEY(id),KEY queue_id(queue_id),KEY event(event),KEY status(status),KEY channel(channel),KEY provider(provider),KEY created_at(created_at)) {$c};"); }
 public static function attempt(int $queue_id,string $event,string $role,int $user_id,string $channel): void { self::write($queue_id,$event,$role,$user_id,$channel,'','attempted','', '', '', [],1); }
 public static function result(int $queue_id,string $event,string $role,int $user_id,string $channel,string $status,string $provider='',string $provider_message_id='',string $error_code='',string $error_message='',array $metadata=[]): void { self::write($queue_id,$event,$role,$user_id,$channel,$provider,$status,$provider_message_id,$error_code,$error_message,$metadata,0); }
 private static function write(int $qid,string $event,string $role,int $uid,string $channel,string $provider,string $status,string $pmid,string $ecode,string $emsg,array $meta,int $attempt): void { global $wpdb; $wpdb->insert(self::table(),['queue_id'=>$qid,'event'=>sanitize_key($event),'role'=>sanitize_key($role),'user_id'=>absint($uid),'channel'=>sanitize_key($channel),'provider'=>sanitize_text_field($provider),'attempt'=>$attempt,'status'=>sanitize_key($status),'provider_message_id'=>sanitize_text_field($pmid),'error_code'=>sanitize_text_field($ecode),'error_message'=>sanitize_textarea_field($emsg),'metadata'=>wp_json_encode($meta),'created_at'=>current_time('mysql')],['%d','%s','%s','%d','%s','%s','%d','%s','%s','%s','%s','%s']); }
 public static function table_name(): string { return self::table(); }
 public static function menu(): void { add_submenu_page('options-general.php','Notification Delivery Analytics','Delivery Analytics','manage_options','avanik-notification-delivery',[self::class,'page']); }
 public static function page(): void { if(!current_user_can('manage_options'))return; global $wpdb; $t=self::table(); $event=sanitize_key($_GET['event']??''); $channel=sanitize_key($_GET['channel']??''); $role=sanitize_key($_GET['role']??''); $days=max(1,min(365,absint($_GET['days']??30))); $since=date('Y-m-d H:i:s',current_time('timestamp')-($days*DAY_IN_SECONDS)); $where=['created_at >= %s'];$args=[$since]; foreach([['event',$event],['channel',$channel],['role',$role]] as $f){if($f[1]){$where[]=$f[0].'=%s';$args[]=$f[1];}} $base=' FROM '.$t.' WHERE '.implode(' AND ',$where); $tot=(int)$wpdb->get_var($wpdb->prepare('SELECT COUNT(*)'.$base,...$args)); $sent=(int)$wpdb->get_var($wpdb->prepare("SELECT COUNT(*){$base} AND status='sent'",...$args)); $failed=(int)$wpdb->get_var($wpdb->prepare("SELECT COUNT(*){$base} AND status IN ('failed','dead')",...$args)); $rate=$tot?round(($sent/$tot)*100,1):0; $channels=$wpdb->get_results($wpdb->prepare('SELECT channel,COUNT(*) total,SUM(status="sent") sent,SUM(status IN ("failed","dead")) failed'.$base.' GROUP BY channel ORDER BY total DESC',...$args),ARRAY_A); $events=$wpdb->get_results($wpdb->prepare('SELECT event,COUNT(*) total,SUM(status="sent") sent,SUM(status IN ("failed","dead")) failed'.$base.' GROUP BY event ORDER BY total DESC LIMIT 50',...$args),ARRAY_A); $recent=$wpdb->get_results($wpdb->prepare('SELECT *'.$base.' ORDER BY id DESC LIMIT 100',...$args),ARRAY_A); echo '<div class="wrap"><h1>Avanik Notification Delivery Analytics</h1><form method="get"><input type="hidden" name="page" value="avanik-notification-delivery"><label>Days <input type="number" name="days" min="1" max="365" value="'.(int)$days.'"></label> <label>Event <input name="event" value="'.esc_attr($event).'"></label> <label>Channel <input name="channel" value="'.esc_attr($channel).'"></label> <label>Role <input name="role" value="'.esc_attr($role).'"></label> <button class="button">Filter</button></form><div style="display:flex;gap:12px;margin:16px 0;flex-wrap:wrap">'; foreach([['Attempts',$tot],['Sent',$sent],['Failed/Dead',$failed],['Success Rate',$rate.'%']] as $m)echo '<div style="background:#fff;border:1px solid #ddd;padding:16px;min-width:140px"><strong>'.esc_html($m[0]).'</strong><br><span style="font-size:24px">'.esc_html((string)$m[1]).'</span></div>'; echo '</div><h2>By Channel</h2><table class="widefat"><thead><tr><th>Channel</th><th>Total</th><th>Sent</th><th>Failed/Dead</th></tr></thead><tbody>';foreach($channels as $r)echo '<tr><td>'.esc_html($r['channel']).'</td><td>'.(int)$r['total'].'</td><td>'.(int)$r['sent'].'</td><td>'.(int)$r['failed'].'</td></tr>';echo '</tbody></table><h2>By Event</h2><table class="widefat"><thead><tr><th>Event</th><th>Total</th><th>Sent</th><th>Failed/Dead</th></tr></thead><tbody>';foreach($events as $r)echo '<tr><td>'.esc_html($r['event']).'</td><td>'.(int)$r['total'].'</td><td>'.(int)$r['sent'].'</td><td>'.(int)$r['failed'].'</td></tr>';echo '</tbody></table><h2>Recent Delivery History</h2><table class="widefat"><thead><tr><th>ID</th><th>Queue</th><th>Event</th><th>Role</th><th>Channel</th><th>Provider</th><th>Status</th><th>Attempt</th><th>Error</th><th>Time</th></tr></thead><tbody>';foreach($recent as $r)echo '<tr><td>'.(int)$r['id'].'</td><td>'.(int)$r['queue_id'].'</td><td>'.esc_html($r['event']).'</td><td>'.esc_html($r['role']).'</td><td>'.esc_html($r['channel']).'</td><td>'.esc_html($r['provider']).'</td><td>'.esc_html($r['status']).'</td><td>'.(int)$r['attempt'].'</td><td>'.esc_html($r['error_code'].' '.$r['error_message']).'</td><td>'.esc_html($r['created_at']).'</td></tr>';echo '</tbody></table></div>'; }
}